/*
 * A096128  Numbers k with the property that reversing the digits and adding
 *          the largest digit produces a prime.
 * https://oeis.org/A096128
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 14, u16 n <= 959, u32 n <= 959, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Computes the n-th term of OEIS A096128: numbers k such that
 * rev(k) + maxdigit(k) is prime; generated by brute‑force search.
 */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

static bool good_term(seq_t k)
{
    seq_t rev   = 0;
    seq_t maxd  = 0;
    seq_t t     = k;
    if (t == 0) return false;     /* 0 is not a term */
    while (t > 0) {
        seq_t d = t % 10;
        if (d > maxd) maxd = d;
        rev = rev * 10 + d;
        t   = t / 10;
    }
    seq_t sum = rev + maxd;
    return is_prime_big(sum);
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;         /* undefined; return 0 for safety */
    seq_t count = 0;
    seq_t cand  = 1;
    while (true) {
        if (good_term(cand)) {
            count++;
            if (count == n) return cand;
        }
        cand++;
    }
}
